const quoteCsv=value=>`"${String(value??'').replaceAll('"','""')}"`

function WalletLedger({title='Wallet transactions',description,transactions,filePrefix,toast}){
  const [search,setSearch]=useState(''),[direction,setDirection]=useState('All'),[status,setStatus]=useState('All'),[from,setFrom]=useState(''),[to,setTo]=useState(''),[page,setPage]=useState(1),[sort,setSort]=useState({key:'date',direction:'desc'})
  const statuses=[...new Set(transactions.map(transaction=>transaction.status))]
  const filtered=useMemo(()=>transactions.filter(transaction=>{
    if(direction!=='All'&&transaction.direction!==direction)return false
    if(status!=='All'&&transaction.status!==status)return false
    if(from&&transaction.date.slice(0,10)<from)return false
    if(to&&transaction.date.slice(0,10)>to)return false
    return !search.trim()||JSON.stringify(transaction).toLowerCase().includes(search.trim().toLowerCase())
  }).sort((a,b)=>{const av=a[sort.key],bv=b[sort.key];const compared=typeof av==='number'?av-bv:String(av??'').localeCompare(String(bv??''),undefined,{numeric:true,sensitivity:'base'});return sort.direction==='asc'?compared:-compared}),[transactions,search,direction,status,from,to,sort])
  const size=5,pages=Math.max(1,Math.ceil(filtered.length/size)),safePage=Math.min(page,pages),visible=filtered.slice((safePage-1)*size,safePage*size)
  const change=(setter,value)=>{setter(value);setPage(1)}
  const sortHead=(label,key)=>{const active=sort.key===key;return <button className="inline-flex items-center gap-1 font-semibold" onClick={()=>{setSort({key,direction:active&&sort.direction==='asc'?'desc':'asc'});setPage(1)}}>{label}<span className={active?'text-saffron-600':'text-brown-300'}>{active?(sort.direction==='asc'?'↑':'↓'):'↕'}</span></button>}
  const exportStatement=()=>{const head=['Date & time','Transaction ID','Campaign ID','Description','Type','Direction','Amount','Status','Linked agent transaction'];const lines=[head,...filtered.map(transaction=>[walletDate(transaction.date),transaction.id,transaction.campaign,transaction.description,transaction.type,transaction.direction,transaction.amount,transaction.status,transaction.linkedTransaction||''])].map(row=>row.map(quoteCsv).join(','));downloadDealerFile(`${filePrefix}-statement.csv`,'text/csv;charset=utf-8',lines.join('\n'));toast(`${filtered.length} wallet transactions exported`)}
  return <section className="card mt-5 overflow-hidden"><div className="flex flex-col gap-3 border-b border-brown-100 p-4 lg:flex-row lg:items-start lg:justify-between"><div><h3 className="font-semibold">{title}</h3><p className="text-xs text-brown-500">{description}</p></div><div className="flex flex-wrap gap-2"><button onClick={exportStatement} className="btn-g !py-2"><Download size={15}/>Export statement</button><label className="btn-g !py-2"><Upload size={15}/>Import statement<input type="file" accept=".csv,.xlsx,.xls" className="sr-only" onChange={event=>{const file=event.target.files?.[0];if(file)toast(`${file.name} selected for statement import`)}}/></label></div></div>
    <div className="space-y-3 border-b border-brown-100 p-4"><Input aria-label="Search wallet transactions" placeholder="Search transaction ID, campaign, listing, type or status" value={search} onChange={event=>change(setSearch,event.target.value)}/><div className="flex flex-col gap-3 xl:flex-row xl:items-end xl:justify-between"><fieldset className="flex flex-wrap gap-2"><legend className="mb-1 text-xs font-semibold uppercase text-brown-500">Transaction</legend>{['All','Credit','Debit'].map(option=><label key={option} className={`cursor-pointer rounded-full border px-3 py-1.5 text-sm font-semibold ${direction===option?'border-brown-900 bg-brown-900 text-white':'border-brown-200 bg-white text-brown-700'}`}><input type="radio" name={`${filePrefix}-direction`} className="sr-only" checked={direction===option} onChange={()=>change(setDirection,option)}/>{option}</label>)}</fieldset><div className="grid gap-2 sm:grid-cols-3"><Field label="Status"><select className="input !py-2" value={status} onChange={event=>change(setStatus,event.target.value)}><option>All</option>{statuses.map(option=><option key={option}>{option}</option>)}</select></Field><Field label="From"><Input type="date" value={from} onChange={event=>change(setFrom,event.target.value)}/></Field><Field label="To"><Input type="date" value={to} onChange={event=>change(setTo,event.target.value)}/></Field></div></div></div>
    <div className="overflow-x-auto"><table className="w-full border-separate border-spacing-0"><thead><tr>{[['Date & time','date'],['Transaction ID','id'],['Campaign ID','campaign'],['For','description'],['Type','type'],['Credit / debit','direction'],['Amount','amount'],['Status','status']].map(([label,key])=><th className="th" key={key}>{sortHead(label,key)}</th>)}</tr></thead><tbody>{visible.map(transaction=><tr key={transaction.id} className="hover:bg-brown-50"><td className="td whitespace-nowrap">{walletDate(transaction.date)}</td><td className="td"><b>{transaction.id}</b>{transaction.linkedTransaction&&<span className="block text-xs text-brown-500">Agent txn: {transaction.linkedTransaction}</span>}</td><td className="td">{transaction.campaign!=='—'?<Pill tone="gold">{transaction.campaign}</Pill>:'—'}</td><td className="td min-w-[230px]">{transaction.description}</td><td className="td">{transaction.type}</td><td className="td"><Pill tone={transaction.direction==='Credit'?'ok':'err'}>{transaction.direction}</Pill></td><td className={`td font-semibold ${transaction.direction==='Debit'?'text-red-700':'text-emerald-700'}`}>{transaction.direction==='Debit'?'−':'+'}{walletMoney(transaction.amount)}</td><td className="td"><Pill tone={transaction.status==='Credited'||transaction.status==='Paid'?'ok':'warn'}>{transaction.status}</Pill></td></tr>)}</tbody></table></div>
    {!filtered.length&&<p className="p-5 text-sm text-brown-500">No matching wallet transactions.</p>}<div className="flex flex-col gap-3 border-t border-brown-100 px-4 py-3 text-sm text-brown-500 sm:flex-row sm:items-center sm:justify-between"><span>{filtered.length?`${(safePage-1)*size+1}–${Math.min(safePage*size,filtered.length)} of ${filtered.length}`:'0 records'}</span><div className="flex items-center gap-2"><button className="btn-g !px-3 !py-1.5" disabled={safePage===1} onClick={()=>setPage(value=>Math.max(1,value-1))}>Previous</button><span>Page {safePage} of {pages}</span><button className="btn-g !px-3 !py-1.5" disabled={safePage===pages} onClick={()=>setPage(value=>Math.min(pages,value+1))}>Next</button></div></div>
  </section>
}

