export function AWallet() {
  const [wd,setWd]=useState(false); const [toast,el]=useToast(); const [specialRewards]=useState(()=>readAgentRewards().filter(record=>record.agentId==='JIN-4471'))
  const specialTransactions=specialRewards.map(record=>({date:record.date,id:rewardTransactionId(record),campaign:record.campaign,description:`Special payout from ${record.staffRole==='moderator'?'Moderator':'Staff'} · ${record.reason} · Listing ${record.listing} · ${record.staffName} (${record.staffId})`,type:'Special reward',amount:Number(record.amount),direction:'Credit',status:'Credited'}))
  const agentTransactions=[...specialTransactions,...agentWalletBase]
  const available=6840+specialRewards.reduce((total,record)=>total+Number(record.amount||0),0)
  return (<AShell>{el}<H t="Wallet" s={<span className="mt-1 flex flex-wrap gap-2"><b className="rounded-full bg-saffron-50 px-3 py-1 text-xs text-saffron-700">Agent ID · JIN-4471</b><b className="rounded-full bg-blue-50 px-3 py-1 text-xs text-blue-800">Dealer · Kozhikode North (Rahul)</b></span>} right={<div className="flex flex-wrap gap-2"><button onClick={downloadAgentId} className="btn-g"><IdCard size={16}/>Download Agent ID</button><Link to="/agent/profile" className="btn-g"><UserRound size={16}/>Agent profile</Link><button onClick={()=>setWd(!wd)} className="btn-p"><Banknote size={16}/>Withdraw</button></div>}/>
    <div className="grid grid-cols-3 gap-3"><Stat v={`₹${available.toLocaleString('en-IN')}`} l="available"/><Stat v="₹2,250" l="pending approval"/><Stat v="₹21,500" l="withdrawn so far"/></div>
    {wd && <div className="card mt-5 p-5"><h3 className="font-semibold">Withdraw to bank / UPI</h3><div className="mt-3 grid gap-4 md:grid-cols-2"><Field label="Amount ₹" hint="Minimum ₹500 · paid in the monthly cycle (next: 30 Sept)"><Input type="number" defaultValue={available}/></Field><Field label="Pay to"><Select options={['UPI jinsha@okaxis','Federal Bank ····8821']}/></Field></div><p className="text-xs text-brown-500">TDS may be deducted as per rules; you'll get a statement.</p><button onClick={()=>{toast(`Withdrawal of ₹${available.toLocaleString('en-IN')} requested`);setWd(false)}} className="btn-p mt-3">Request ₹{available.toLocaleString('en-IN')}</button></div>}
    <WalletLedger title="Agent wallet transaction ledger" description="Search, filter and sort every credit or debit. Staff rewards include both transaction and campaign IDs." transactions={agentTransactions} filePrefix="agent-JIN-4471-wallet" toast={toast}/>
    <div className="card mt-5 p-5 text-sm"><b>Territory rates (Kozhikode North)</b><div className="text-brown-500">Listing approved ₹100 · KYC ₹200 · Plan 15% · Sponsorship 15% · Renewal 5% · Special pooja via your link 5% · Fee revenue from your listings 10% for 12 months</div></div></AShell>)
}

