const staffNav = role => {
  const q = `?role=${role}`
  if (role==='moderator') return [{group:'Moderation',links:[['/staff'+q,'Queues',Inbox],['/staff/listing'+q,'Listing review',ListChecks],['/staff/kyc'+q,'KYC & agents',ShieldCheck],['/staff/charts'+q,'Daily charts',CalendarCheck],['/staff/special'+q,'Special poojas',Sparkles],['/staff/ownership'+q,'Claims & transfers',ArrowRightLeft],['/staff/support'+q,'Support tickets',MessageCircle]]}]
  if (role==='accountant') return [{group:'Finance',links:[['/staff'+q,'Finance queues',Inbox],['/staff/payouts'+q,'Payout NEFT batches',Landmark],['/staff/withdrawals'+q,'Wallet withdrawal NEFT',HandCoins],['/staff/sponsors'+q,'Payments received',Banknote]]}]
  return [{group:'Work queues',links:[['/staff'+q,'Queues',Inbox],['/staff/analytics'+q,'Analytics',BarChart3],['/staff/payouts'+q,'Payouts',Landmark],['/staff/listing'+q,'Listing review',ListChecks],['/staff/kyc'+q,'KYC',ShieldCheck],['/staff/charts'+q,'Charts',CalendarCheck],['/staff/special'+q,'Special poojas',Sparkles],['/staff/withdrawals'+q,'Wallet withdrawals',HandCoins],['/staff/ownership'+q,'Claims & transfers',ArrowRightLeft],['/staff/sponsors'+q,'Sponsors & plans',Banknote],['/staff/backup'+q,'Backup & restore',Database]]},{group:'Portal admin',links:[['/staff/wallet-credit'+q,'Manual wallet points',Wallet],['/staff/config'+q,'Configuration',Settings2],['/staff/tables'+q,'Advanced → tables',Table2]]}]
}
const staffRoleLabel = {moderator:'Staff · Moderator', accountant:'Staff · Accountant', admin:'Staff · Portal admin'}
const useStaffRole = () => { const [sp]=useSearchParams(); return staffRoleLabel[sp.get('role')] ? sp.get('role') : 'admin' }
export const SShell = ({children}) => { const [sp]=useSearchParams(); const role = staffRoleLabel[sp.get('role')] ? sp.get('role') : 'admin'
  const names={moderator:'Anand · Moderator',accountant:'Deepa · Accountant',admin:'Anand · Portal admin'}
  const directory={group:'Directories',links:[['/staff/directory/users','All users',Users],['/staff/directory/transactions','All transactions',Banknote]].map(([path,label,icon])=>[path+'?role='+role,label,icon])}
  return <DashShell role={staffRoleLabel[role]} user={names[role]} items={[...staffNav(role),...(role==='accountant'?[]:[directory])]} badge={role==='moderator'?'28':role==='accountant'?'7':'24'}>{children}</DashShell> }
const Q = ({c,t,s,h,hot,role}) => { const activeRole=role||useStaffRole(); return <Link to={`${h}?role=${activeRole}`} className="card flex items-center gap-3 p-4 transition hover:shadow-soft"><span className={`grid h-11 w-11 place-items-center rounded-xl text-lg font-bold ${hot?'bg-saffron-50 text-saffron-600':'bg-brown-50 text-brown-800'}`}>{c}</span><span className="flex-1"><b className="block text-sm">{t}</b><span className="text-xs text-brown-500">{s}</span></span><span className="btn-g !py-1.5 text-xs">Open</span></Link> }

const reviewPath = (queue,id,role='moderator') => `/staff/review/${queue}/${id}?role=${role}`
const QueueTable = ({head,rows,searchKeys,filterKey,filterLabel='Status',filterOptions=[]}) => {
  const [query,setQuery]=useState(''); const [filter,setFilter]=useState('All'); const [page,setPage]=useState(1); const size=4
  const found=rows.filter(r=>(filter==='All'||String(r[filterKey])===filter)&&searchKeys.some(k=>String(r[k]||'').toLowerCase().includes(query.toLowerCase())))
  const pages=Math.max(1,Math.ceil(found.length/size)); const safePage=Math.min(page,pages); const shown=found.slice((safePage-1)*size,safePage*size)
  return <div className="card overflow-hidden"><div className="border-b border-brown-100 p-4"><label className="relative block"><Search size={16} className="absolute left-3 top-3 text-brown-400"/><input value={query} onChange={e=>{setQuery(e.target.value);setPage(1)}} placeholder="Search name, code or creator" className="input pl-9"/></label>{filterOptions.length>0&&<fieldset className="mt-3 flex flex-wrap items-center gap-2"><legend className="mr-1 inline text-xs font-semibold uppercase text-brown-500">{filterLabel}</legend>{['All',...filterOptions].map(x=><label key={x} className={`cursor-pointer rounded-full border px-3 py-1.5 text-sm font-semibold transition ${filter===x?'border-brown-900 bg-brown-900 text-white':'border-brown-200 bg-white text-brown-700 hover:bg-brown-50'}`}><input type="radio" name={`${filterLabel}-filter`} value={x} checked={filter===x} onChange={e=>{setFilter(e.target.value);setPage(1)}} className="sr-only"/>{x}</label>)}</fieldset>}</div><Table head={head} rows={shown.map(r=>r.cells)}/><div className="flex items-center justify-between border-t border-brown-100 px-4 py-3 text-sm text-brown-500"><span>{found.length?`${(safePage-1)*size+1}–${Math.min(safePage*size,found.length)} of ${found.length}`:'No matching records'}</span><div className="flex items-center gap-2"><button className="btn-g !px-3 !py-1.5" disabled={safePage===1} onClick={()=>setPage(p=>Math.max(1,p-1))}>Previous</button><span>Page {safePage} of {pages}</span><button className="btn-g !px-3 !py-1.5" disabled={safePage===pages} onClick={()=>setPage(p=>Math.min(pages,p+1))}>Next</button></div></div></div>
}
const ModeratorActions = ({queue,id,preview,toast}) => <div className="flex min-w-max flex-wrap gap-1.5"><Link target="_blank" rel="noreferrer" to={reviewPath(queue,id)} className="btn-g !px-2.5 !py-1.5 text-xs"><Eye size={13}/>View</Link>{preview&&<Link target="_blank" rel="noreferrer" to={preview} className="btn-g !px-2.5 !py-1.5 text-xs"><ExternalLink size={13}/>Preview</Link>}<button onClick={()=>toast(`${id} approved`)} className="btn !bg-emerald-50 !px-2.5 !py-1.5 text-xs text-emerald-700"><Check size={13}/>Approve</button><button onClick={()=>toast(`${id} reverted to its creator`)} className="btn !bg-saffron-50 !px-2.5 !py-1.5 text-xs text-saffron-700"><RotateCcw size={13}/>Revert</button><button onClick={()=>toast(`Message composer opened for ${id}`)} className="btn-g !px-2.5 !py-1.5 text-xs"><MessageCircle size={13}/>Message</button></div>

